<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import AppModal from '@trama/components/AppModal.vue'
import ModalConfirm from '@trama/components/ModalConfirm.vue'
import FluxCanvas from '@trama/components/flux/FluxCanvas.vue'
import FluxStepConfigDrawer from '@trama/components/flux/FluxStepConfigDrawer.vue'
import { graphEdges, layoutGraph } from '@trama/components/flux/graphModel'
import { db, deleteFlux, deleteFluxVersion, duplicateFlux, getFlux, renameFluxVersion, restoreFluxVersion, runFlux, saveFluxVersion, toggleFluxStatus, updateFlux } from '@trama/services/api'
import { getApp } from '@trama/services/apps'
import { getBlockState } from '@trama/utils/subscription'
import { toastError, toastInfo, toastSuccess } from '@trama/composables/useToast'

const route=useRoute(), router=useRouter(), canvas=useTemplateRef('canvas'), importInput=useTemplateRef('importInput')
const flux=ref(null), loading=ref(true), loadError=ref(''), selectedId=ref(null), statuses=ref({}), testOutputs=ref({}), running=ref(false)
const pendingSave=ref(false), saving=ref(false), saveError=ref(''), publishing=ref(false), stateModal=ref(false), deleteOpen=ref(false)
const editingName=ref(false), nameDraft=ref(''), versionsOpen=ref(false), executionsOpen=ref(false), renamingVersion=ref(null), versionName=ref('')
const terminalOpen=ref(false), terminalTab=ref('input'), inputText=ref('{}'), inputError=ref(''), lastExecution=ref(null), selectedLog=ref(null), settingsOpen=ref(false)
const now=ref(Date.now()), undoStack=ref([]), redoStack=ref([])
let saveTimer, clock, savePromise=null, saveAgain=false, abortRun=null, loadedId=null, dirtyRevision=0, disposed=false
const clone=(v)=>JSON.parse(JSON.stringify(v))
const block=computed(()=>getBlockState(db.subscription,'integration'))
const selectedStep=computed(()=>flux.value?.steps.find(s=>String(s.id)===selectedId.value)??null)
const selectedIndex=computed(()=>flux.value?.steps.findIndex(s=>String(s.id)===selectedId.value)??-1)
const outputs=computed(()=>({ ...Object.fromEntries((lastExecution.value?.steps??[]).filter(s=>s.output!==undefined).map(s=>[s.id,s.output])), ...testOutputs.value }))
const hasUnpublished=computed(()=>!flux.value?.published_version_id || JSON.stringify(draftSnapshot())!==JSON.stringify(publishedSnapshot()))
const availableHandlers=computed(()=>(db.fluxes??[]).filter(f=>f.id!==flux.value?.id).map(f=>({title:f.name,value:f.id})))
const lastSaved=computed(()=>{const delta=Math.max(0,(now.value-new Date(flux.value?.updated_at??now.value).getTime())/1000);return delta<60?'alguns segundos':delta<3600?`${Math.floor(delta/60)} minutos`:delta<86400?`${Math.floor(delta/3600)} horas`:`${Math.floor(delta/86400)} dias`})

function draftSnapshot(){ if(!flux.value)return{};return {steps:clone(flux.value.steps??[]),edges:clone(flux.value.edges??[]),settings:clone(flux.value.settings??{}),test_input:clone(flux.value.test_input??{})} }
function publishedSnapshot(){const version=flux.value?.versions?.find(v=>v.id===flux.value.published_version_id||v.active);const snap=version?.snapshot??version;return snap?{steps:snap.steps??[],edges:snap.edges??[],settings:snap.settings??{},test_input:snap.test_input??{}}:{} }
function remember(){undoStack.value.push(draftSnapshot());if(undoStack.value.length>80)undoStack.value.shift();redoStack.value=[]}
function restoreDraft(snapshot){Object.assign(flux.value,clone(snapshot));selectedId.value=null;inputText.value=JSON.stringify(flux.value.test_input??{},null,2);scheduleSave()}
function undo(){if(!undoStack.value.length)return;redoStack.value.push(draftSnapshot());restoreDraft(undoStack.value.pop())}
function redo(){if(!redoStack.value.length)return;undoStack.value.push(draftSnapshot());restoreDraft(redoStack.value.pop())}

async function load(){
  const id=String(route.params.fluxId??'')
  if(!id){loadError.value='Abra ou crie uma integração para começar.';loading.value=false;return}
  clearTimeout(saveTimer);loading.value=true;loadError.value='';selectedId.value=null;saveError.value='';pendingSave.value=false
  try{const record=await getFlux(id);if(String(route.params.fluxId)!==id)return;record.steps??=[];record.edges=graphEdges(record.steps,record.edges);record.settings={minimap:true,...record.settings};record.test_input??={};flux.value=record;loadedId=id;inputText.value=JSON.stringify(record.test_input,null,2);lastExecution.value=record.executions?.[0]??null;statuses.value={};testOutputs.value={};undoStack.value=[];redoStack.value=[];document.title=`Trama | ${record.name}`}
  catch(error){loadError.value=error.userMessage||error.message||'Não foi possível carregar esta integração.'}
  finally{loading.value=false}
}
onMounted(()=>{load();clock=setInterval(()=>now.value=Date.now(),30000);window.addEventListener('keydown',keyboard);window.addEventListener('beforeunload',beforeUnload)})
watch(()=>route.params.fluxId,async()=>{if(pendingSave.value&&flux.value?.id===loadedId)await persist();await load()})
onBeforeRouteLeave(async()=>{if(pendingSave.value){const saved=await persist();if(!saved)return false}return true})
onBeforeUnmount(()=>{disposed=true;clearInterval(clock);clearTimeout(saveTimer);abortRun?.abort();window.removeEventListener('keydown',keyboard);window.removeEventListener('beforeunload',beforeUnload)})
function beforeUnload(event){if(pendingSave.value||saving.value){event.preventDefault();event.returnValue=''}}
function keyboard(event){const target=event.target;if(target?.closest?.('input,textarea,[contenteditable="true"],.v-overlay--active'))return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();publish()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redo():undo()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redo()}}
function scheduleSave(){dirtyRevision++;pendingSave.value=true;saveError.value='';clearTimeout(saveTimer);saveTimer=setTimeout(persist,700)}
async function persist(){
  clearTimeout(saveTimer)
  if(!flux.value)return false
  if(savePromise){saveAgain=true;await savePromise;if(pendingSave.value)return persist();return !saveError.value}
  const id=flux.value.id,revision=dirtyRevision,snapshot={name:flux.value.name,...draftSnapshot()};saving.value=true
  savePromise=(async()=>{try{const saved=await updateFlux(id,snapshot);if(flux.value?.id===id){flux.value.updated_at=saved.updated_at;pendingSave.value=revision!==dirtyRevision;saveError.value=''}return true}catch(error){pendingSave.value=true;saveError.value=error.userMessage||error.message||'Não foi possível salvar.';return false}finally{saving.value=false}})()
  const success=await savePromise;savePromise=null
  if(saveAgain){saveAgain=false;if(pendingSave.value&&!saveError.value&&!disposed)return persist()}
  return success
}
function startRename(){nameDraft.value=flux.value.name;editingName.value=true}
function commitRename(){const name=nameDraft.value.trim();if(!name||name.length>50){toastError({text:'O nome deve ter entre 1 e 50 caracteres.'});return}editingName.value=false;if(name!==flux.value.name){flux.value.name=name;scheduleSave();document.title=`Trama | ${name}`}}
async function confirmState(){try{if(pendingSave.value&&!(await persist()))return;const saved=await toggleFluxStatus(flux.value.id,!flux.value.active);flux.value.active=saved?.active??!flux.value.active;toastInfo({text:flux.value.active?'A integração foi ativada. Os gatilhos usam a versão publicada.':'A integração foi inativada.'})}catch(error){toastError({text:error.userMessage||error.message})}}
function onMove(id,position,done){const step=flux.value.steps.find(s=>String(s.id)===id);if(!step)return;if(position)step.position=position;if(done)scheduleSave()}
function updateEdges(edges){remember();flux.value.edges=clone(edges);scheduleSave()}
function nextId(){const numeric=flux.value.steps.map(s=>Number(String(s.id).replace(/^s[-_]?/,''))).filter(Number.isFinite);return String(Math.max(0,...numeric)+1)}
function addStep(context){
  const {app,module:moduleDef,appDefinition,sourceId,sourceHandle='out',position}=typeof context==='string'?{app:context}:context
  remember();const source=flux.value.steps.find(s=>String(s.id)===sourceId),positions=layoutGraph(flux.value.steps,flux.value.edges)
  const step={id:nextId(),app,action:getApp(app).title,config:{},position:position??{x:(positions[sourceId]?.x??-290)+290,y:positions[sourceId]?.y??0}}
  if(moduleDef&&appDefinition) Object.assign(step,{title:appDefinition.name,action:moduleDef.name,description:moduleDef.description??'',module_id:moduleDef.id,parameters_json:clone(moduleDef.parameters_json??[]),definition:clone({base:appDefinition.base,request:moduleDef.request,revision:appDefinition.revision,app_id:appDefinition.id,module_id:moduleDef.id})})
  if(source?.app==='router'){const branch=Number(sourceHandle.replace('branch-',''))||1;step.position.y+=(branch-1)*230-115}
  if(sourceHandle==='body')step.position.y-=115
  if(sourceHandle==='done')step.position.y+=115
  flux.value.steps.push(step)
  if(source)flux.value.edges.push({id:crypto.randomUUID(),source:sourceId,target:step.id,sourceHandle,...(sourceHandle!=='out'?{branch:sourceHandle}:{})})
  selectedId.value=step.id;scheduleSave()
}
function removeStep(id=selectedId.value){const index=flux.value.steps.findIndex(s=>String(s.id)===id);if(index<0)return;if(getApp(flux.value.steps[index].app).trigger){toastInfo({text:'O gatilho inicia a integração. Configure-o para alterar o recebimento.'});return}remember();flux.value.steps.splice(index,1);flux.value.edges=flux.value.edges.filter(e=>e.source!==id&&e.target!==id);selectedId.value=null;delete testOutputs.value[id];scheduleSave()}
function duplicateStep(id){const source=flux.value.steps.find(s=>String(s.id)===id);if(!source||getApp(source.app).trigger)return;remember();const pos=layoutGraph(flux.value.steps,flux.value.edges)[id];const copy={...clone(source),id:nextId(),position:{x:pos.x+30,y:pos.y+250}};flux.value.steps.push(copy);scheduleSave()}
function disconnectStep(id){remember();flux.value.edges=flux.value.edges.filter(edge=>edge.source!==id&&edge.target!==id);scheduleSave()}
function addBranch(id){const step=flux.value.steps.find(s=>String(s.id)===id);if(step?.app!=='router')return;remember();step.config??={};step.config.branches=Math.max(2,Number(step.config.branches)||2)+1;scheduleSave()}
function updateSelectedStep(draft){if(!selectedStep.value)return;remember();Object.assign(selectedStep.value,clone(draft));scheduleSave()}
function updateInput(input){remember();flux.value.test_input=clone(input);inputText.value=JSON.stringify(input,null,2);scheduleSave()}
function organize(){remember();const positions=layoutGraph(flux.value.steps,flux.value.edges,{preserve:false});for(const step of flux.value.steps)step.position=positions[step.id];scheduleSave();nextTick(()=>canvas.value?.fitView())}
async function publish(){if(publishing.value)return;publishing.value=true;try{if(!(await persist()))throw new Error(saveError.value);const saved=await saveFluxVersion(flux.value.id);flux.value.versions=saved.versions;flux.value.published_version_id=saved.published_version_id;toastSuccess({title:'Integração publicada',text:'Esta versão está guardada no histórico do seu fluxo.'})}catch(error){toastError({title:'Não foi possível publicar',text:error.userMessage||error.message})}finally{publishing.value=false}}

function executionEvent(event){
  const type=event.type??event.event
  if(type==='execution:start'){lastExecution.value={id:event.executionId,status:'running',steps:[],started_at:new Date().toISOString(),origin:'Terminal de testes',input:clone(flux.value.test_input)};return}
  const id=String(event.nodeId??event.step?.id??'')
  if(type==='node:start')statuses.value={...statuses.value,[id]:'running'}
  if(type==='node:finish'){const step=event.step??event;statuses.value={...statuses.value,[id]:step.status??event.status??'success'};if(!lastExecution.value)lastExecution.value={status:'running',steps:[]};lastExecution.value.steps.push(clone({...step,id}));if(step.output!==undefined)testOutputs.value={...testOutputs.value,[id]:step.output}}
  if(type==='execution:finish'&&event.execution)lastExecution.value=event.execution
}
async function run(){
  if(running.value){abortRun?.abort();return}
  let input
  try{input=JSON.parse(inputText.value||'{}');inputError.value=''}catch{inputError.value='A entrada precisa ser um JSON válido.';terminalOpen.value=true;terminalTab.value='input';return}
  if(JSON.stringify(input)!==JSON.stringify(flux.value.test_input)){flux.value.test_input=input;scheduleSave()}
  if(pendingSave.value&&!(await persist())){toastError({text:saveError.value});return}
  running.value=true;statuses.value={};testOutputs.value={};abortRun=new AbortController();terminalOpen.value=true;terminalTab.value='logs'
  try{const execution=await runFlux(flux.value.id,{input,onEvent:executionEvent,signal:abortRun.signal});lastExecution.value=execution;statuses.value=Object.fromEntries((execution.steps??[]).map(step=>[step.id,step.status]));if(execution.status==='error')toastError({title:'Erro na execução',text:typeof execution.error==='string'?execution.error:execution.error?.message||'Veja o nó indicado nos logs.'});else if(execution.status==='cancelled')toastInfo({text:'Execução cancelada.'});else toastSuccess({title:'Execução concluída',text:`${execution.steps?.length??0} etapas executadas.`});await refreshExecutionHistory()}
  catch(error){if(error.name==='AbortError'){if(lastExecution.value)lastExecution.value.status='cancelled';toastInfo({text:'Cancelamento solicitado.'})}else toastError({text:error.userMessage||error.message})}
  finally{running.value=false;abortRun=null}
}
async function refreshExecutionHistory(){try{const saved=await getFlux(flux.value.id);flux.value.executions=saved.executions??[];flux.value.activations=saved.activations;flux.value.average_execution=saved.average_execution}catch{ /* The executed result remains visible if the history refresh fails. */ }}
function tested(execution){const step=execution.step??execution.steps?.find(s=>String(s.id)===selectedId.value);const output=step?.output??execution.output;if(output!==undefined)testOutputs.value={...testOutputs.value,[selectedId.value]:output};statuses.value={...statuses.value,[selectedId.value]:step?.status??execution.status??'success'};if(execution.steps)lastExecution.value=execution;refreshExecutionHistory()}
function formatDate(iso){if(!iso)return'';return new Date(iso).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'medium'})}
async function restoreVersion(version){try{if(pendingSave.value&&!(await persist()))return;const restored=await restoreFluxVersion(flux.value.id,version.id);flux.value={...flux.value,...restored,edges:graphEdges(restored.steps,restored.edges)};inputText.value=JSON.stringify(flux.value.test_input??{},null,2);undoStack.value=[];redoStack.value=[];versionsOpen.value=false;toastSuccess({text:'Versão restaurada.'})}catch(error){toastError({text:error.userMessage||error.message})}}
async function saveVersionName(version){const name=versionName.value.trim();if(!name||name.length>80)return;try{await renameFluxVersion(flux.value.id,version.id,name);version.name=name;renamingVersion.value=null}catch(error){toastError({text:error.userMessage||error.message})}}
async function removeVersion(version){try{await deleteFluxVersion(flux.value.id,version.id);flux.value.versions=flux.value.versions.filter(v=>v.id!==version.id)}catch(error){toastError({text:error.userMessage||error.message})}}
function exportFlux(){const version=flux.value.versions?.find(v=>v.id===flux.value.published_version_id||v.active);if(!version){toastInfo({text:'Publique uma versão antes de exportar a integração.'});return}const content={format:'caramelo-trama',format_version:1,name:flux.value.name,published_version_id:version.id,...clone(version.snapshot??{steps:version.steps,edges:version.edges,settings:version.settings,test_input:version.test_input})};const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'}));link.href=url;link.download=`${flux.value.name.replace(/[<>:"/\\|?*]/g,'_')}.json`;link.click();URL.revokeObjectURL(url)}
async function importFlux(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw new Error('O arquivo excede 10 MB.');const data=JSON.parse(await file.text());if(!Array.isArray(data.steps)||!data.steps.every(s=>s&&typeof s.app==='string'))throw new Error('Formato de integração inválido.');const ids=data.steps.map((s,i)=>String(s.id??i));if(new Set(ids).size!==ids.length)throw new Error('O arquivo possui IDs de nós duplicados.');remember();flux.value.steps=data.steps.map((s,i)=>({...clone(s),id:ids[i]}));flux.value.edges=graphEdges(flux.value.steps,data.edges);flux.value.settings={minimap:true,...clone(data.settings??{})};flux.value.test_input=clone(data.test_input??{});inputText.value=JSON.stringify(flux.value.test_input,null,2);selectedId.value=null;scheduleSave();await persist();nextTick(()=>canvas.value?.fitView());toastSuccess({text:'Integração importada no rascunho. Salve uma versão para guardar este estado do fluxo.'})}catch(error){toastError({text:error.message||'Arquivo inválido.'})}}
async function duplicate(){try{if(pendingSave.value&&!(await persist()))return;const copy=await duplicateFlux(flux.value.id);await router.push({name:'flux',params:{fluxId:copy.id}})}catch(error){toastError({text:error.userMessage||error.message})}}
async function remove(){try{await deleteFlux(flux.value.id);pendingSave.value=false;clearTimeout(saveTimer);await router.push({name:'home'})}catch(error){toastError({text:error.userMessage||error.message})}}
</script>

<template>
  <div class="flux-editor">
    <div v-if="loading" class="editor-loading"><v-progress-circular indeterminate color="primary" /></div>
    <div v-else-if="loadError" class="editor-loading"><v-icon icon="mdi-alert-circle-outline" size="44" color="warning" /><p>{{ loadError }}</p><v-btn color="primary" to="/">Voltar ao início</v-btn></div>
    <template v-else-if="flux">
      <FluxCanvas ref="canvas" :steps="flux.steps" :edges="flux.edges" :selected-id="selectedId" :statuses="statuses" :controls-top="94" :minimap="flux.settings.minimap!==false" @select="selectedId=$event" @move="onMove" @add="addStep" @update:edges="updateEdges" @duplicate="duplicateStep" @delete="removeStep" @disconnect="disconnectStep" @add-branch="addBranch" @background-click="selectedId=null" />
      <header class="flux-overlay">
        <div class="editor-heading"><button class="back-button" aria-label="Voltar ao início" @click="router.push('/')"><v-icon icon="mdi-chevron-left" size="24" /></button><input v-if="editingName" v-model="nameDraft" class="name-editor" autofocus maxlength="50" aria-label="Nome da integração" @keyup.enter="commitRename" @keyup.esc="editingName=false" @blur="commitRename" /><button v-else class="editable-title" @click="startRename">{{ flux.name }} <v-icon icon="mdi-pencil-outline" size="19" /></button></div>
        <div class="editor-tools"><div class="toolbar-row"><span class="activation-label">Execução manual</span><v-switch :model-value="flux.active" :disabled="true" title="Execução manual disponível em Rodar; ativação automática ainda indisponível" inset density="compact" hide-details color="primary" class="activation-toggle" aria-label="Ativar integração" @update:model-value="stateModal=true" /><button class="tool-button" aria-label="Controle de versão" @click="versionsOpen=true"><v-icon icon="mdi-graph-outline" class="mdi-rotate-180" /><v-tooltip activator="parent">Controle de versão</v-tooltip></button><button class="tool-button" aria-label="Organizar integração" @click="organize"><v-icon icon="mdi-auto-fix" /><v-tooltip activator="parent">Organizar integração</v-tooltip></button><button class="tool-button" :class="{publishing}" :disabled="publishing||saving" aria-label="Publicar integração" @click="publish"><v-progress-circular v-if="publishing" indeterminate size="19" width="2" /><v-icon v-else icon="mdi-content-save-outline" /><v-tooltip activator="parent">Salvar e publicar integração</v-tooltip></button><button class="tool-button run-button" :class="{running}" :aria-label="running?'Cancelar execução':'Rodar integração'" @click="run"><v-icon :icon="running?'mdi-stop':'mdi-play-outline'" size="21" /><span>{{ running?'CANCELAR':'RODAR' }}</span></button><button class="tool-button" aria-label="Execuções" @click="executionsOpen=true"><v-icon icon="mdi-list-box-outline" /><v-tooltip activator="parent">Execuções</v-tooltip></button><v-menu location="bottom end"><template #activator="{props:menuProps}"><button v-bind="menuProps" class="more-button" aria-label="Opções da integração"><v-icon icon="mdi-dots-vertical" /></button></template><v-card min-width="330" class="options-menu"><h4>Opções da integração</h4><v-switch v-model="flux.settings.halt_on_error" label="Pausar automaticamente após erro" color="primary" density="compact" hide-details @update:model-value="scheduleSave" /><v-switch v-model="flux.settings.minimap" label="Minimapa" color="primary" density="compact" hide-details @update:model-value="scheduleSave" /><v-btn variant="text" block prepend-icon="mdi-alert-outline" @click="settingsOpen=true">Tratamento de erros</v-btn><v-divider class="my-2" /><v-list density="compact" bg-color="transparent"><v-list-item title="Exportar integração" prepend-icon="mdi-download-outline" @click="exportFlux" /><v-list-item title="Importar integração" prepend-icon="mdi-upload-outline" @click="importInput.click()" /><v-list-item title="Duplicar integração" prepend-icon="mdi-content-copy" @click="duplicate" /><v-list-item title="Excluir integração" prepend-icon="mdi-delete-outline" base-color="error" @click="deleteOpen=true" /></v-list></v-card></v-menu></div><div class="save-state" :class="{'save-failed':saveError}"><span v-if="saveError" @click="persist" role="button" tabindex="0">{{ saveError }} · Tentar novamente</span><span v-else-if="saving">Salvando alterações...</span><span v-else-if="pendingSave">Alterações não salvas</span><span v-else>Salvo por último há {{ lastSaved }}</span><span v-if="hasUnpublished" class="draft-indicator" title="Alterações ainda não guardadas em uma versão">Rascunho</span></div></div>
      </header>
      <div class="editor-bottom-tools"><button class="terminal-toggle" @click="terminalOpen=!terminalOpen"><v-icon icon="mdi-console-line" size="16" /> Terminal <v-icon :icon="terminalOpen?'mdi-chevron-down':'mdi-chevron-up'" size="16" /></button><button class="history-button" :disabled="!undoStack.length" title="Desfazer (Ctrl+Z)" aria-label="Desfazer" @click="undo"><v-icon icon="mdi-undo" size="18" /></button><button class="history-button" :disabled="!redoStack.length" title="Refazer (Ctrl+Shift+Z)" aria-label="Refazer" @click="redo"><v-icon icon="mdi-redo" size="18" /></button></div>
      <section v-if="terminalOpen" class="execution-terminal"><header><button :class="{active:terminalTab==='input'}" @click="terminalTab='input'">Entrada de teste</button><button :class="{active:terminalTab==='logs'}" @click="terminalTab='logs'">Execução <span v-if="lastExecution">{{ lastExecution.status }}</span></button><span class="terminal-caption">{{ lastExecution?.id }}</span><button class="terminal-close" aria-label="Fechar terminal" @click="terminalOpen=false"><v-icon icon="mdi-close" size="18" /></button></header><div v-if="terminalTab==='input'" class="terminal-input"><textarea v-model="inputText" aria-label="JSON de entrada de teste" spellcheck="false" /><div><p>Dados usados ao rodar o rascunho. Os gatilhos automáticos usam a versão publicada.</p><p v-if="inputError" class="text-error">{{ inputError }}</p><v-btn color="primary" :loading="running" prepend-icon="mdi-play-outline" @click="run">Rodar com esta entrada</v-btn></div></div><div v-else class="terminal-logs"><p v-if="!lastExecution" class="terminal-empty">Nenhuma execução. Configure uma entrada e rode a integração.</p><template v-else><div class="terminal-log-list"><button v-for="(step,index) in lastExecution.steps" :key="`${step.id}-${index}`" :class="{selected:selectedLog===index}" @click="selectedLog=index"><v-icon :icon="step.status==='error'?'mdi-alert-circle':step.status==='running'?'mdi-loading':'mdi-check-circle'" :color="step.status==='error'?'error':'success'" size="16" /><b>{{ step.id }}</b><span>{{ getApp(step.app).title }}</span><small>{{ step.ms??0 }} ms</small></button><p v-if="running&&!lastExecution.steps?.length" class="terminal-empty">Iniciando execução...</p></div><div class="terminal-log-output"><template v-if="lastExecution.steps?.[selectedLog??lastExecution.steps.length-1]"><pre>{{ JSON.stringify(lastExecution.steps[selectedLog??lastExecution.steps.length-1],null,2) }}</pre></template><pre v-else>{{ JSON.stringify(lastExecution.error??lastExecution.output??{},null,2) }}</pre></div></template></div></section>
      <FluxStepConfigDrawer v-if="selectedStep" :key="selectedStep.id" :step="selectedStep" :index="selectedIndex" :all-steps="flux.steps" :edges="flux.edges" :flux-id="flux.id" :test-input="flux.test_input" :outputs="outputs" :last-execution="lastExecution" @close="selectedId=null" @update="updateSelectedStep" @input-update="updateInput" @delete="removeStep()" @tested="tested" />
      <input ref="importInput" type="file" accept=".fiqon,.json,.trama" hidden @change="importFlux" />
      <ModalConfirm v-model="stateModal" :header-text="flux.active?'Inativar integração?':'Ativar integração?'" :confirm-text="flux.active?'INATIVAR':'ATIVAR'" close-on-confirm @confirm="confirmState"><p>{{ flux.active?'Os próximos disparos automáticos serão bloqueados.':'Os gatilhos executarão a versão publicada desta integração.' }}</p></ModalConfirm>
      <ModalConfirm v-model="deleteOpen" header-text="Excluir integração?" confirm-text="Excluir integração" close-on-confirm @confirm="remove"><p>A integração <b>{{ flux.name }}</b> e seus gatilhos serão removidos.</p></ModalConfirm>
      <AppModal v-model="settingsOpen" width="520"><h3 class="mb-5">Tratamento de erros</h3><v-switch v-model="flux.settings.halt_on_error" label="Pausar a integração após erro" hide-details @update:model-value="scheduleSave" /><v-select v-model="flux.settings.error_handler_flux_id" :items="availableHandlers" label="Em caso de erro, ativar outra integração" clearable class="mt-4" @update:model-value="scheduleSave" /><p class="text-caption mt-3">O tratamento recebe a entrada, o erro e as saídas já produzidas.</p></AppModal>
      <AppModal v-model="versionsOpen" width="min(92vw,740px)"><h3 class="mb-5">Versões da integração</h3><p v-if="!flux.versions?.length">Nenhuma versão publicada. Use Salvar e publicar para criar a primeira.</p><div v-for="version in flux.versions" :key="version.id" class="version-row"><template v-if="renamingVersion===version.id"><v-text-field v-model="versionName" label="Nome da versão" density="compact" hide-details @keyup.enter="saveVersionName(version)" /><v-btn icon="mdi-check" size="small" variant="text" @click="saveVersionName(version)" /></template><template v-else><div class="version-description"><strong>{{ version.name }}</strong><small>{{ formatDate(version.created_at) }}</small></div><v-chip v-if="version.id===flux.published_version_id||version.active" size="small" color="primary">Publicada</v-chip><v-btn v-else variant="tonal" size="small" @click="restoreVersion(version)">Restaurar</v-btn><v-btn icon="mdi-pencil-outline" variant="text" size="small" aria-label="Renomear versão" @click="renamingVersion=version.id;versionName=version.name" /><v-btn icon="mdi-delete-outline" variant="text" size="small" aria-label="Excluir versão" :disabled="version.id===flux.published_version_id||version.active" @click="removeVersion(version)" /></template></div></AppModal>
      <AppModal v-model="executionsOpen" width="min(92vw,880px)"><div class="executions-heading"><h3>Execuções</h3><v-btn variant="text" color="primary" :to="{name:'flux-dashboard',params:{fluxId:flux.id}}">Histórico de execuções <v-icon icon="mdi-open-in-new" size="16" class="ml-2" /></v-btn></div><p v-if="!flux.executions?.length">Nenhuma execução realizada.</p><div v-for="execution in flux.executions" :key="execution.id" class="execution-row"><v-icon :icon="execution.status==='error'?'mdi-alert-circle':'mdi-check-circle'" :color="execution.status==='error'?'error':'success'" size="21" /><div><strong>{{ formatDate(execution.started_at) }}</strong><small>{{ execution.origin }} · {{ execution.duration_ms??0 }} ms · {{ execution.operations??0 }} operações</small></div><v-btn size="small" variant="tonal" @click="lastExecution=execution;executionsOpen=false;terminalOpen=true;terminalTab='logs';selectedLog=null">Ver logs</v-btn></div></AppModal>
    </template>
  </div>
</template>

